<script setup>
import PublicLayout from '../../Layouts/PublicLayout.vue';
import { router } from '@inertiajs/vue3';
import { Search, BookOpen, ArrowRight } from 'lucide-vue-next';
import { reactive } from 'vue';
const props=defineProps({archives:Object,categories:Array,filters:Object});
const form=reactive({search:props.filters?.search||'',category:props.filters?.category||'',year:props.filters?.year||''});
const apply=()=>router.get('/archives',form,{preserveState:true,replace:true});
</script>
<template><PublicLayout>
<section class="bg-[#00351F] text-white"><div class="mx-auto max-w-7xl px-5 py-14 lg:px-8"><p class="text-xs font-bold uppercase tracking-[.22em] text-[#D4A72C]">BBHS Heritage & Memory</p><h1 class="mt-3 text-4xl font-extrabold sm:text-5xl">Historical Archives</h1><p class="mt-4 max-w-2xl text-white/75">Explore the people, milestones, achievements and memories that have shaped the BBHS Old Boys Association.</p></div></section>
<section class="bg-[#F7F9F7] py-10"><div class="mx-auto max-w-7xl px-5 lg:px-8"><div class="mb-8 grid gap-3 rounded-2xl border bg-white p-4 md:grid-cols-[1fr_240px_130px_auto]"><input v-model="form.search" @keyup.enter="apply" placeholder="Search the archive..." class="rounded-lg border-gray-200"/><select v-model="form.category" class="rounded-lg border-gray-200"><option value="">All categories</option><option v-for="c in categories" :key="c">{{c}}</option></select><input v-model="form.year" type="number" placeholder="Year" class="rounded-lg border-gray-200"/><button @click="apply" class="rounded-lg bg-[#006B3C] px-5 py-2 font-bold text-white"><Search class="mr-2 inline" :size="16"/> Search</button></div>
<div v-if="!archives.data?.length" class="rounded-2xl bg-white p-12 text-center text-gray-500">No published archive records match your search yet.</div><div v-else class="grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><article v-for="item in archives.data" :key="item.id" class="overflow-hidden rounded-2xl border bg-white shadow-sm"><img v-if="item.cover_image" :src="`/storage/${item.cover_image}`" class="h-48 w-full object-cover"/><div v-else class="flex h-40 items-center justify-center bg-[#EEF8F2] text-[#006B3C]"><BookOpen :size="42"/></div><div class="p-6"><p class="text-xs font-bold uppercase tracking-wider text-[#006B3C]">{{item.category}} <span v-if="item.record_year">· {{item.record_year}}</span></p><h2 class="mt-2 text-xl font-extrabold text-[#00351F]">{{item.title}}</h2><p class="mt-3 line-clamp-3 text-sm leading-6 text-gray-600">{{item.summary}}</p><a :href="`/archives/${item.slug}`" class="mt-5 inline-flex items-center gap-2 text-sm font-bold text-[#006B3C]">Explore record <ArrowRight :size="16"/></a></div></article></div>
<div v-if="archives.links?.length" class="mt-8 flex flex-wrap gap-2"><a v-for="link in archives.links" :key="link.label" :href="link.url||'#'" v-html="link.label" class="rounded border bg-white px-3 py-2 text-sm" :class="{'opacity-40 pointer-events-none':!link.url,'bg-[#006B3C] text-white':link.active}"/></div></div></section></PublicLayout></template>
